const {realVar, vectorVar, vec} = Symbolic;
const {fitData} = DataScience;
let trainXs = NArray.range(0,1000).map(x => 2 * Math.random() - 1);
let testXs = NArray.range(0,1000).map(x => 2 * Math.random() - 1);
let yf = x => 4 * x * x * x - 2 * x * x + 3 * x-3 + 1 * (2 * Math.random() - 1);
let {scene} = IO.plotPointCloud(trainXs.map(x => [x, yf(x)]));
let x = realVar("x", true);
let a = vectorVar("a",4);
let f = vec(1, x, x.mul(x), x.mul(x).mul(x)).dot(a);
const { compiledModel, theta} = fitData(trainXs, trainXs.map(x => yf(x)), f);
IO.plotPointCloud(testXs.map(x => [x, compiledModel({x, ...theta})]), {scene, color:[0,0,1]});
